<script setup lang="ts">
import {ref} from 'vue';import {useRouter} from 'vue-router';import {authClient,errorMessage} from '../api';import {useAuth} from '../stores/auth';import PageHeader from '../components/PageHeader.vue';
const auth=useAuth(),router=useRouter(),currentPassword=ref(''),newPassword=ref(''),confirmation=ref(''),busy=ref(false),error=ref(''),success=ref('');
async function change(){error.value='';success.value='';if(newPassword.value!==confirmation.value){error.value='La confirmación no coincide con la nueva contraseña.';return;}busy.value=true;try{const r=await authClient.changePassword({currentPassword:currentPassword.value,newPassword:newPassword.value,revokeOtherSessions:true});if(r.error)throw new Error('No se pudo cambiar la contraseña. Revisa la contraseña actual.');currentPassword.value='';newPassword.value='';confirmation.value='';await auth.load();success.value='Contraseña actualizada.';router.replace(auth.user?.role==='preparacion'?'/comandas':'/dashboard');}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
</script>
<template><PageHeader title="Mi cuenta" description="Seguridad y datos de acceso" /><section class="card narrow"><h2>{{auth.user?.name}}</h2><p class="muted">{{auth.user?.username}}</p><p v-if="auth.user?.mustChangePassword" class="notice">Cambia tu contraseña inicial para comenzar a usar el sistema.</p><form class="stack" @submit.prevent="change"><label>Contraseña actual<input v-model="currentPassword" type="password" required autocomplete="current-password" /></label><label>Nueva contraseña<input v-model="newPassword" type="password" required minlength="10" maxlength="128" autocomplete="new-password" /></label><label>Confirmar nueva contraseña<input v-model="confirmation" type="password" required minlength="10" maxlength="128" autocomplete="new-password" /></label><p class="muted small">Usa al menos 10 caracteres.</p><p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="success" class="notice success" role="status">{{success}}</p><button :disabled="busy">{{busy?'Guardando…':'Cambiar contraseña'}}</button></form></section></template>
